  FT["PH-H5066"] = {"id":"PH-H5066","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6568_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of the Laguna Provincial Hospital Located in the Municipality of Sta. Cruz, Province of Laguna, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Increasing the Bed Capacity of the Laguna Provincial Hospital Located in the Municipality of Sta. Cruz, Province of Laguna, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6568","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6568_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5066-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Laguna Provincial Hospital located in the Municipality of Sta. Cruz, Province of Laguna is hereby increased from one hundred twenty-five to one hundred fifty beds."}},{"id":"PH-H5066-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos or so much thereof as may be necessary is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, in addition to the present appropriation for the hospital, for the operation maintenance of the additional beds, as well as for necessary facilities thereof. Thereafter, such sums as may be necessary for the same purpose shall be included in the General Appropriations Act."}},{"id":"PH-H5066-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5067"] = {"id":"PH-H5067","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6569_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Marihatag市","en":"An Act Establishing a National Emergency Hospital in the Municipality of Marihatag, Province of Surigao Del Sur, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a National Emergency Hospital in the Municipality of Marihatag, Province of Surigao Del Sur, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6569","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6569_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5067-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, a national emergency hospital in the Municipality of Marihatag, Province of Surigao del Sur."}},{"id":"PH-H5067-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred seventy-one. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5067-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval on September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5068"] = {"id":"PH-H5068","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6570_1972.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Oton市","en":"An Act Establishing An Emergency Hospital in the Municipality of Oton, Province of Iloilo, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Oton, Province of Iloilo, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6570","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6570_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5068-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, an emergency hospital in the Municipality of Oton, Province of Iloilo, to be known as Oton Emergency Hospital."}},{"id":"PH-H5068-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5068-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred seventy-one. Thereafter, the necessary sums for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5068-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5069"] = {"id":"PH-H5069","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6571_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing Two Emergency Hospitals in the Province of Albay, One in the Municipality of Guinobatan and the Other in the Municipality of Oas, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing Two Emergency Hospitals in the Province of Albay, One in the Municipality of Guinobatan and the Other in the Municipality of Oas, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6571","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6571_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5069-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, two emergency hospitals in the Province of Albay, one in the Municipality of Guinobatan and the other in the Municipality of Oas."}},{"id":"PH-H5069-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of these hospitals during the fiscal year nineteen hundred seventy one at two hundred fifty thousand pesos each. Thereafter, such sums as may be needed for their operation and maintenance shall be included in the annual General appropriations Act."}},{"id":"PH-H5069-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5070"] = {"id":"PH-H5070","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6572_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Virac市","en":"An Act Converting the Provincial Hospital in the Municipality of Virac, Province of Catanduanes, Into a General Hospital and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Converting the Provincial Hospital in the Municipality of Virac, Province of Catanduanes, Into a General Hospital and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6572","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6572_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5070-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provincial hospital in the Municipality of Virac Province of Catanduanes, is hereby converted into a general hospital to be known as Catanduanes General Hospital."}},{"id":"PH-H5070-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one million pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the conversion, operation and maintenance of said hospital during the fiscal year nineteen hundred seventy-one. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5070-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5071"] = {"id":"PH-H5071","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6573_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Balasan市","en":"An Act Establishing An Emergency Hospital in the Municipality of Balasan, Province of Iloilo, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Balasan, Province of Iloilo, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6573","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6573_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5071-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established in the Municipality of Balasan, Province of Iloilo, an emergency hospital to be known as Balasan Emergency Hospital."}},{"id":"PH-H5071-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of three hundred thousand pesos authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintainance of said hospital during the fiscal year nineteen hundred seventy. Thereafter, such sum as may be needed for its operation maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5071-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
