  FT["PH-H5076"] = {"id":"PH-H5076","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6578_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sta市","en":"An Act Establishing An Emergency Hospital in the Municipality of Sta. Maria, Province of Laguna, to Be Known as Sta. Maria Emergency Hospital, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Sta. Maria, Province of Laguna, to Be Known as Sta. Maria Emergency Hospital, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6578","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6578_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5076-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established in the Municipality of Sta. Maria, Province of Laguna, an emergency hospital, under the supervision of the Bureau of Medical hospital, Services, to be known as Sta. maria Emergency Hospital."}},{"id":"PH-H5076-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In order to carry out the purposes of this Act, the sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National treasury not otherwise appropriated, which shall be expended for the operation, maintenance, and the acquisition of site as well as for the purchase and seventy-two. Thereafter, such sum as may be necessary for the same purposes shall be included in the annual General Appropriations Act."}},{"id":"PH-H5076-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"this Act shall effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5077"] = {"id":"PH-H5077","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6579_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of Ziga Memorial Hospital in the Municipality of Tabaco, Province of Albay, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Increasing the Bed Capacity of Ziga Memorial Hospital in the Municipality of Tabaco, Province of Albay, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6579","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6579_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5077-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of Ziga Memorial Hospital in the Municipality of Tabaco, Province of Albay, hereby increased from twenty-five beds to fifty beds."}},{"id":"PH-H5077-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act during the fiscal year nineteen hundred seventy-two. Thereafter, such sum as may be necessary for the maintenance of the said number of beds shall be included in the annual General Appropriations Act."}},{"id":"PH-H5077-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5078"] = {"id":"PH-H5078","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6580_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Narvacan市","en":"An Act Converting Central Ilocos Sur Emergency Hospital in the Municipality of Narvacan, Province of Ilocos Sur, Into a Fifty-Bed Capacity General Hospital to Be Known as Jacob-Laya General Hospital, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Converting Central Ilocos Sur Emergency Hospital in the Municipality of Narvacan, Province of Ilocos Sur, Into a Fifty-Bed Capacity General Hospital to Be Known as Jacob-Laya General Hospital, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6580","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6580_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5078-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Central Ilocos Sur Emergency Hospital in the Municipality of Narvacan, Province of Ilocos Sur, is hereby converted into a general hospital to be known as the Jacob-Laya General Hospital. This hospital shall have a fifty-bed capacity."}},{"id":"PH-H5078-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In addition to the appropriation of said hospital under Republic Act Numbered Three thousand seven hundred and seventy-seven, the sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said hospital during the fiscal year nineteen hundred seventy-two and nineteen hundred seventy-three. Thereafter, the said amounts and such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5078-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
