  FT["PH-H5083"] = {"id":"PH-H5083","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6585_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing a School of Arts and Trades in the Muncipality of Prosperidad, Province of Agusan Del Sur to Be Known as the Agusan Del Sur School of Arts and Trades, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing a School of Arts and Trades in the Muncipality of Prosperidad, Province of Agusan Del Sur to Be Known as the Agusan Del Sur School of Arts and Trades, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 6585","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6585_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5083-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Director of Vocational Education, a school of arts and trades in the Municipality of Prosperidad, Province of Agusan del Sur, to be known as the Agusan del Sur School of Arts and Trades: Provided, however , That only a general education curriculum with Practical arts shall be offered in the first and second years, and the vocational education curriculum shall be offered in the third and fourth years: Provided, further , That the school shall offer short vocational courses for training in vocations needed in the locality which shall be open to elementary school graduates: Provided, finally , That the school shall open, as soon as feasible, two-year post secondary technical courses."}},{"id":"PH-H5083-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred seventy-one. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5083-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5084"] = {"id":"PH-H5084","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6586_1972.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating a Juvenile and Domestic Relations Court in the Province of Cebu and Appropriating Funds Therefor.","orig":"An Act Creating a Juvenile and Domestic Relations Court in the Province of Cebu and Appropriating Funds Therefor."},"level":"law","status":"active","topics":["judiciary","civil"],"docNumber":"Republic Act No. 6586","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6586_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5084-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Juvenile and Domestic Relations Court . -There shall be created one Juvenile and Domestic Relations Court in the Province of Cebu for which a judge who shall possess the same qualifications, enjoy the same privileges and receive the same salary as judge of the Court of First Instance, shall be appointed by the President of the Philippines with the consent of the Commission on Appointments.\nProvisions of the Judiciary Act to the contrary notwithstanding, the court shall have exclusive original jurisdiction to hear and decide the following cases in the Province of Cebu including the cities of Cebu, Lapu-Lapu, Toledo, Danao and Mandawe:\na. Criminal cases wherein the accused is under sixteen years of age at the time of the trial;\nb. Cases involving custody, guardianship, adoption, paternity and acknowledgement;\nc. Annulment of marriages, legal separation of spouses, and action for support;\nd. Proceedings brought under the provisions of Article one hundred sixteen, two hundred twenty-five, two hundred fifty-two and three hundred thirty-two of the Civil Code;\ne. Petitions for the declaration of absence and for the change of name;\nf. Actions for the separation of property of spouses;\ng. Proceedings affecting a dependent or neglected child, as hereinafter defined.\nThe court shall likewise have such incidental powers as are generally possessed by courts of first instance.\nIf any question involving any of the above matters should arise as an incident in any case pending in the ordinary courts, said incident shall be determined in the main case."}},{"id":"PH-H5084-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Dependent' or 'neglected' child defined .-The term 'dependent' child or 'neglected' child shall mean any child under sixteen years of age who is dependent upon the public for support or who is destitute, homeless or abandoned; or who habitually begs or receives alms, or who is found living in any house of ill fame or with any vicious or disreputable person, or whose home, by reason of neglect, cruelty or depravity on the part of its parents, guardian or other person in whose care it may be, is an unfit place for such child."}},{"id":"PH-H5084-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Proceedings concerning a 'dependent' or 'neglected - child.-Any representative of the Secretary of the Department of Social Welfare who is assigned in the city, having knowledge of a child in the province or city who appears to be 'dependent' or 'neglected' child may file with the clerk of the court a written petition, setting forth the facts constituting the child 'dependent' or 'neglected'; which petition shall be verified by the affidavit of the petitioner. It shall be sufficient, if the affidavit shall be upon information and belief. Such petition shall set forth the name of the parent or parents of such child, if known, and their residence; and if such child has no parent living, then name and residence of the guardian of such child, if it has one.\nUpon the filing of such petition, the judge of said court shall fix the day and time for the hearing of such petition. If it appears that one or both of such parents, or guardian, if there be no parents, reside in the province, the clerk of said court shall immediately issue summons, which shall include a copy of the petition, and which shall be served on such parent, parents, or guardian, if any, if either can be found in the province or city not less than two days before the time fixed for said hearing, requiring them to appear on said day and hour to show cause, if any, why such child should not be declared by said court to be a 'dependent' or 'neglected' child. If it appears from the petition that neither of said parents is living, or do not reside in the province or city and that said child has no guardian residing in said province, or in case one or both of said parents, or the guardian in case there be no parents, shall indorse on said petition a request that the child be declared a 'dependent' child, then the summons herein provided for shall not be issued; and the court may thereupon proceed to a hearing of the case. In case neither of the parents or guardian is found, then the court shall appoint some suitable person to represent said child in said case.\nUpon such hearing of such case the child shall be brought before said court; whereupon, the court shall investigate the facts, and ascertain whether the child is a -dependent' child, its residence, and, as far as possible, the whereabouts of its parents or near adult relatives, when and how long the child has been maintained in whole or in part, by private or public charity, the occupation of the parents, if living, whether they are supported by the public or have abandoned the child, and to ascertain, as far possible, if the child is found dependent, the cause thereof. The court may compel the attendance of witnesses on such examination. The fiscal, when requested by the court, shall appear in any such examination in behalf of the petitioner. It shall be the duty of the fiscal upon the request of the court or any petitioner, to file a petition and to conduct any necessary proceedings in any case within the provisions of this article.\nIn the hearing of such case, the court shall not be bound to follow the technical rules of evidence. If the said child shall be found after such hearing to be a 'dependent' or 'neglected' child, as defined herein, it shall be adjudged a 'dependent' child, and an order may be entered making such disposition of the care and custody of said child as the court deems best for its moral and physical welfare. It may be turned over to the care and custody of any suitable person or any suitable institution in the city organized for the purpose of caring for 'dependent' children, and which is able and willing to care for same. If there be no such person or suitable institution, the child shall be referred to the Department of Social Welfare. And when such child is so turned over to the custody of such person or institution, such person or institution shall have the right to the custody of said child, and shall be at all times responsible for its education and maintenance, subject at all times to the order of the court.\nIn any case where the court shall award any 'dependent or 'neglected' child to the care of any individual or institution, the child, unless otherwise ordered, shall become a ward and be subject to the guardianship of the institution or individual to whose care it is committed. Any institution or individual receiving any such child under the order of the court shall be subject to visitation or inspection by any person appointed by the court for such purpose; and the court may, at any time, require any institution or person a report containing such information as the court shall deem proper or necessary to be fully advised as to the care, education, maintenance and moral and physical training of the child; as well as to the standing and ability of such institution or individual to care for such child. The court may change the guardianship of such child, if, at any time, it is made to appear to the court such change is to the best interests of the child. If, in the opinion of the court, the causes of the dependency of any child may be removed under such conditions or supervision for its care, protection and maintenance as may be imposed by the court, so long as it shall be for its best interests, the child may be permitted to remain in its own home and under the care and control of its own parent, parents or guardian, subject to the jurisdiction and direction of the court; and when it shall appear to the court that it is no longer to the best interests of such child to remain with such parents or guardian, the court may proceed to a final disposition of the case.\nIn case any child is adjudged to be 'dependent' or 'neglected' then such parents or guardian shall thereafter have no right over or to the custody or services of said child except upon such condition in the interests of such child as the court may impose, or where, upon proper proceedings, such child may lawfully be restored to the parents for guardian."}},{"id":"PH-H5084-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Proceedings in other cases .-In the hearing and disposition of cases other than that covered by the preceding section, the court shall be governed by the Rules of Court and the laws properly applicable in each particular case.\nIn cases between husband and wife, and between parent and child, however, the hearings may be held, upon petition of any party, in chamber or with the exclusion of the public. All information obtained at such hearings shall be deemed privileged and confidential and shall not be divulged without approval of the court."}},{"id":"PH-H5084-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Appeal from decision and order of the Court .- Decisions and orders of the court shall be appealed in the same manner and subject to the same conditions as appeals from the courts of first instance."}},{"id":"PH-H5084-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The clerk of court and subordinate employees .- The Juvenile and Domestic Relations Court shall be court of record and shall have a clerk of court and such subordinate employees as may be necessary who shall be appointed in the same manner and shall receive the same compensation as similar officials and employees of the Court of First Instance."}},{"id":"PH-H5084-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Upon the organization of the Juvenile and Domestic Relations Court, the Secretary of Justice shall cause all cases: and proceedings pending before any court properly cognizable by the court herein created to be transferred thereto."}},{"id":"PH-H5084-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Such sum as may be necessary to carry out the purpose of this Act during the fiscal year nineteen hundred seventy to nineteen hundred seventy -one is appropriated, out of any funds in the National Treasury not otherwise appropriated. The same sum needed for the same purpose in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H5084-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5085"] = {"id":"PH-H5085","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6587_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Nasipit市","en":"An Act Establishing a National Vocational School in the Municipality of Nasipit, Province of Agusan Del Norte, to Be Known as Nasipit National Vocational School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a National Vocational School in the Municipality of Nasipit, Province of Agusan Del Norte, to Be Known as Nasipit National Vocational School, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6587","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6587_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5085-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a national vocational school in the Municipality of Nasipit, Province of Agusan del Norte, to be known as Nasipit National Vocational School: Provided, however , That only a general education curriculum with practical arts shall be offered in the first and second years, and the vocational education curriculum shall be offered in the third and fourth years: Provided, further , That the school shall offer short vocational courses for training in vocations needed in the locality which shall be open to elementary school graduates : Provided, finally , That the school shall open, as soon as feasible, two-year post-secondary technical courses."}},{"id":"PH-H5085-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated for the establishment, operation and maintenance of said school for the fiscal year nineteen hundred seventy-one. Thereafter, the necessary sum for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5085-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5086"] = {"id":"PH-H5086","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6588_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing a School of Nursing and Midwifery in the Provincial Hospital of Samar Situated in Catbalogan, Province of Samar, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing a School of Nursing and Midwifery in the Provincial Hospital of Samar Situated in Catbalogan, Province of Samar, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["education","health"],"docNumber":"Republic Act No. 6588","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6588_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5086-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a school of nursing and midwifery in the Provincial Hospital of Samar situated in Catbalogan, Province of Samar. Said school shall be under the supervision of the Director of Medical Services."}},{"id":"PH-H5086-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred seventy-two. There after such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5086-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5087"] = {"id":"PH-H5087","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6589_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Paniqui市","en":"An Act Establishing a National Vocational High School in the Municipality of Paniqui, Province of Tarlac, to Be Known as Tarlac National Vocational High School, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing a National Vocational High School in the Municipality of Paniqui, Province of Tarlac, to Be Known as Tarlac National Vocational High School, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6589","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6589_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5087-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a national vocational high school in the Municipality of Paniqui, Province of Tarlac, to be known as Tarlac National Vocational High School; Provided, however , That only a general education curriculum with practical arts courses shall be offered in the first and second, years, and the vocational education curriculum shall be offered in the third and fourth years: Provided, further ; That the school shall offer short vocational courses for training in vocations needed in the locality which shall be open to elementary school graduates: Provided, finally , That the School open, as soon as feasible, two-year post secondary technical courses."}},{"id":"PH-H5087-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of seven hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment of said school including the acquisition of the necessary site therefor and its operation and maintenance during the fiscal year nineteen hundred seventy-two. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5087-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5088"] = {"id":"PH-H5088","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6590_1972.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for Additional Courses to Be Offered in the Catanduanes State Colleges, Amending for the Purpose Certain Sections of Republic Act Numbered Sixty-Three Hundred Forty-One.","orig":"An Act Providing for Additional Courses to Be Offered in the Catanduanes State Colleges, Amending for the Purpose Certain Sections of Republic Act Numbered Sixty-Three Hundred Forty-One."},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6590","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6590_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5088-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Sixty-three hundred forty-one is amended to read as follows:\n\""}},{"id":"PH-H5088-A1_2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Virac National Agricultural and Trade School in the Municipality of Virac, Province of Catanduanes, is hereby converted into a college to be known as Catanduanes State Colleges, hereinafter called Colleges, which shall offer two-year courses leading to the titles of Associate in Arts in Nursing, Associate in Arts in Education, Associate in Business Education, Associate in Commerce; courses leading to the degrees of Bachelor of Arts, Bachelor of Science, Bachelor of Science in Agriculture, Bachelor of Science in Forestry, Bachelor of Laws, Bachelor of Science in Civil Engineering, Bachelor of Science in Mechanical Engineering, Bachelor Science in Electrical Engineering, Bachelor of Science in Elementary Education, Bachelor of Science in Business Education, Bachelor of Science in Commerce and Bachelor of Science in Education, and courses leading to degrees of Master of Arts in Business Education, Master of Arts in Education, and Master of Arts in Commerce, and such other courses that the Board Trustees may authorize.\""}},{"id":"PH-H5088-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subparagraph (c), Section six of the same Act is amended to read as follows:\n\"(c) To confer to successful candidates for graduation such titles and degrees authorized to be offered in Section one of this Act;\""}},{"id":"PH-H5088-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, September 30, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5089"] = {"id":"PH-H5089","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6591_1972.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating a Juvenile and Domestic Relations Court for the Province of Camarines Sur and the Cities of Naga and Iriga.","orig":"An Act Creating a Juvenile and Domestic Relations Court for the Province of Camarines Sur and the Cities of Naga and Iriga."},"level":"law","status":"active","topics":["judiciary","civil"],"docNumber":"Republic Act No. 6591","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6591_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5089-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Juvenile and Domestic Relations Court. There shall be a Juvenile and Domestic Relations Court for the Province of Camarines Sur, the City of Naga and the City of Iriga, with permanent station in the City of Naga but with authority to conduct hearings and investigations in any city or municipality within its jurisdiction as the court may consider to be in the interest of justice.\nThe court shall be presided by a judge who shall have the same qualification, rank, compensation, rights and privileges as judges of courts of first instance; and, in addition, shall be one who is thoroughly familiar with the culture, mores, dialect, traditions and family life of the people within the jurisdiction of the court; who has demonstrated a sincere interest in social action and has at least ten years of successful experience in social work, teaching or other similar work dealing with family relations, juveniles and the youth in general; who has obtained sufficient academic training in psychology and guidance, preferably one with a Master's degree in said studies, social work or education; and who has had substantial experience, preferably gained as member of the Bench, in the impartial settlement of conflicts and in arriving at acceptable compromises. The judge, who may or may not be a resident of the province or cities within the jurisdiction of the court, shall be appointed President of the Philippines with the consent of the Commission on Appointments.\n(a) Criminal cases wherein the accused is under sixteen years of age at the time of the filing of the case and which, at present, are cognizable by courts of first instance, city courts and municipal courts, except cases involving violations of municipal ordinances of the City of Iriga and of the different municipalities of Camarines Sur;\n(b) Cases involving custody, guardianship, adoption, paternity and acknowledgment;\n(c) Annulment of marriages, relief from marital obligations, legal separation of spouses, and actions for support;\n(d) Proceedings brought under the provisions of Articles one hundred sixteen, one hundred seventeen, two hundred twenty-five, two hundred fifty-one, and three hundred thirty-two of the Civil Code;\n(e) Proceedings for declaration of absence and for change of name;\n(f) Actions involving separation of property and other property relations between spouses;\n(g) Proceedings affecting a dependent or neglected child as hereinafter defined or other cases concerning the exercise or deprivation of parental authority.\nThe court shall have such incidental powers as are generally possessed by courts of first instance.\nIf any question involving any of the above matters should arise as an incident in any case pending in the ordinary courts, said incident shall be determined in the main case.\nIn case of the temporary absence, disqualification, or inhibition of the judge, the Secretary of Justice may designate a Judge of the Court of First Instance to act in the court or on a particular case in accordance with the procedures provided for under this Act. Such designation may also be made under the conditions provided in the first paragraph of Section fifty-one of the Judiciary Act.\nFor the more economical and expeditious disposition of cases pending before it, the court shall have the authority to designate any judge of an inferior court within its jurisdiction to act as a commissioner for the purpose of receiving evidence in the city or municipality wherein he is stationed. Such commissioner shall proceed to receive evidence without delay and shall submit to the court a full report of the proceedings under him within twenty days after the termination of said proceedings. The court shall have the discretion either to render a decision on the basis of the commissioner's report thus submitted, or require the commissioner to receive further evidence, or conduct further hearings itself."}},{"id":"PH-H5089-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"\"Dependent\" or \"neglected\" child defined. The term \"dependent child\" or \"neglected child\" shall mean any child under sixteen years of age who is dependent upon the public for support or who is destitute, homeless or abandoned; or who has no proper parental care or guardianship, or who habitually begs or receives alms, or who is found living in any house of ill-fame or with any vicious or disreputable person, or whose home or other place of residence, by reason of neglect, cruelty or depravity on the part of its parents, guardian or other person in whose care the child may be, is an unfit place for such child."}},{"id":"PH-H5089-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Proceedings concerning a \"dependent\" or \"neglected\" child. The Secretary of Social Welfare or his representative who is assigned within the jurisdiction of the Court, having knowledge of a child within said jurisdiction who appears to be a \"dependent\" or \"neglected\" child, must file with the clerk of court a written petition setting forth the facts constituting the child \"dependent\" or \"neglected\", which petition shall be verified by the affidavit of the petitioner and to which shall be annexed a summarized report on the case study on which the petition is based. It shall be sufficient if the affidavit shall be upon information and belief. Such petition shall set forth the name and residence of the parent or parents of such child, if known; and if such child has no parent living, then the name and residence of the guardian of such child, if it has one.\nUpon filing of the petition, if the interest of the child so warrants, the court may take custody of the child for placement with any person, institution or agency authorized to care for children during the trial of the case. The court or the commissioner, if one has been designated, shall fix the day, time and place for the hearing of such petition. If it appears that one or both of the parents, or guardian, if there be no parents, reside within the jurisdiction of the court, the clerk of court concerned shall immediately issue summons, which shall include a copy of the petition, and which shall be served on such parent, parents, or guardian, if any, if either can be found within said jurisdiction, not less than two days before the time fixed for said hearing, requiring them to appear on said place, day and hour to show cause, if any there be, why such child should not be declared a \"dependent\" or \"neglected\" child. If it appears from the petition that neither of the parents is living, or do not reside within the jurisdiction of the court, and that said child has no guardian residing within said jurisdiction, or in case one or both of said parents, or the guardian in case in there are no parents, shall indorse on said petition a request that the child be declared a \"dependent\" child then the summons herein provided shall not be issued; and the court or the commissioner may thereupon proceed to a hearing of the case. In case neither of the parents nor guardian is found, the court shall appoint some suitable person to represent said child in said case.\nUpon the hearing of such case the child shall be brought before the court or commissioner; whereupon the court or the commissioner shall investigate the facts, and ascertain whether the child is a \"dependent\" or \"neglected\" child, its residence, and, as far as possible, the whereabouts of its parents or adult near-relatives, when and how long the child has been maintained, in whole or in part, by private or public charity, the occupation of the parents, if living, whether they are supported by the public or have abandoned the child, and to ascertain, as far as possible, if the child is found dependent, the cause therefor. The court may compel the attendance of witnesses on such examinations. The provincial or city fiscal, concerned, when requested by the court of the commissioner, shall appear in such examination in behalf of the petitioner. It shall be the duty of such fiscal, upon the request of the court or any petitioner, to file a petition and to conduct any necessary proceedings in any case within the provisions of this Act.\nIn the hearing of such case, the court or the commissioner shall not be found to follow the technical rules of evidence. If the said child shall be found after such hearing to be \"dependent\" or neglected\" child, as herein defined, it shall be so adjudged, and an order may be entered making such disposition of the case and custody of said child as the court deems best for its moral and physical welfare. It may be turned over to the care and custody of any suitable person or institution in the province or city, which has been organized for the purpose of caring for \"dependent\" or \"neglected\" children, and which is able and willing to care for the same. If there be no such suitable person or institution, the child shall be referred to the Department of Social Welfare. And when the child is so turned over to the custody of such person or institution, such person or institution shall have the right to the custody of said child, and shall be at all times responsible for its education and maintenance subject at all times to the order of the court.\nIn any case where the court shall award any \"dependent\" or \"neglected\" child to the care of any individual or institution, the child, unless otherwise ordered, shall become a ward and be subject to the guardianship of the institution or individual to whose care it is committed. Any institution or individual receiving any such child under the order of the court shall be subject to the visitation or inspection by any person appointed by the court for such purpose, and the court may at any time, require from the institution or person, a report containing such information as the court shall deem proper and necessary, to be fully advise to the care, education, maintenance and moral and physical training of the child, as well as to the standing and ability of such institution or individual to care for such child. The court may change the guardianship of such child, if, at any time, it is made to appear to the court that such change is to the best interests of the child. If, in the opinion of the court, the causes of the dependency of any child may be removed under such conditions or supervision for its care, protection and maintenance as may be imposed by the court, so long as it shall be for its best interests, the child may be permitted to remain in its own home under the care and control of its own parent, parents or guardian, subject to the jurisdiction and direction of the court, and when it shall appear to the court that it is no longer to the best interests of such child to remain with such parents or guardian, the court may proceed to a final disposition of the case.\nIn case any child is adjudged to be \"dependent\" or \"neglected\" then such parents or guardian shall thereafter have no right over or to the custody or services of said child except upon such conditions in the interest of such child as the court may impose, or where, upon proper proceedings, such child may lawfully be restored to the parents or guardian. Before ordering such restoration, the court may require the parents or guardian to make such reimbursements for the previous expenses of the child or to agree to such other conditions as the court may impose."}},{"id":"PH-H5089-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Proceedings in other cases. In the hearing and disposition of cases other than those covered by the preceding section, the court shall be governed by the Rules of Court and the law properly applicable in each particular case, but said rules shall be applied most liberally along pre-trial philosophy.\nIn cases between husband and wife, and between parent and child, the hearing may be held, upon petition of any party, in chamber or with the exclusion of the public. All information obtained at such hearings shall be deemed privileged and confidential and shall not be divulged without approval of the court."}},{"id":"PH-H5089-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Appeal from decision and order of the court. Decisions and orders of the court shall be appealed in the same manner and subject to the same conditions as appeals from courts of first instance."}},{"id":"PH-H5089-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The clerk of court and subordinate employees. The Juvenile and Domestic Relations Court shall be a court of record and shall have a clerk of court and such subordinate employees as may be necessary who, upon the recommendation of the judge, shall be appointed in the same manner and shall receive the same compensation as similar officials and employees of the courts of first instance."}},{"id":"PH-H5089-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Court facilities, supplies and allowances. The same facilities, equipment, supplies and allowances as are given to courts of first instance shall be furnished by the Province of Camarines Sur. The Secretary of Justice, upon the request of the province, may require the Cities of Iriga and Naga to share in these costs."}},{"id":"PH-H5089-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Seminars. The Judge of Juvenile and Domestic Relations Court, at least once a year during the first three years after its creation and thereafter whenever he finds it appropriate, shall call a conference of or conduct a seminar for municipal and city judges and other government personnel involved in carrying out of the provisions of this Act to discuss procedures, psychological and guidance problems, family relations and other matters conducive to the fulfillment of the objectives of this Act."}},{"id":"PH-H5089-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Transitory provisions. Upon the organization of the Juvenile and Domestic Relations Court, the Secretary of Justice shall cause all cases and proceedings pending before the courts of first instance, municipal courts and city courts in the Province of Camarines Sur and the Cities of Naga and Iriga, properly cognizable by said court to be transferred thereto."}},{"id":"PH-H5089-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Appropriation. Such sum as may be necessary to carry out the purpose of this Act during the fiscal year nineteen hundred seventy-two to nineteen hundred seventy-three is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, and such similar amount and for the same purpose shall thereafter be included in the annual General Appropriations Act."}},{"id":"PH-H5089-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: September 30, 1974"}}],"pack":"ph-p72"};
  FT["PH-H5090"] = {"id":"PH-H5090","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6592_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Malimono市","en":"An Act Establishing a School of Fisheries in the Municipality of Malimono, Province of Surigao Del Norte, to Be Known as the Malimono School of Fisheries, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing a School of Fisheries in the Municipality of Malimono, Province of Surigao Del Norte, to Be Known as the Malimono School of Fisheries, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 6592","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6592_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5090-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a school of fisheries in the Municipality of Malimono, Province of Surigao del Norte, to be known as the Malimono School of Fisheries: Provided, however , That only a general education curriculum with practical arts shall be offered in the first and second years, and the vocational education curriculum shall be offered in the third and fourth years: Provided, further , That the school shall offer short vocational courses for training in vocations needed in the locality which shall be open to elementary school graduates: Provided, finally , That the school shall open, as soon as feasible, two-year post secondary technical courses."}},{"id":"PH-H5090-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred Seventy-three. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5090-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5091"] = {"id":"PH-H5091","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6593_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Magallanes市","en":"An Act Establishing a School of Fisheries in the Municipality of Magallanes, Province of Sorsogon, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing a School of Fisheries in the Municipality of Magallanes, Province of Sorsogon, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 6593","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6593_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5091-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational Education, a school of fisheries in the Municipality of Magallanes, Province of Sorsogon, to be known as the Magallanes School of Fisheries: Provided, however, That only a general education curriculum with practical arts shall be offered in the first and second years, and the vocational curriculum shall be offered in the third and fourth years: Provided, further, That the school shall offer short vocational courses for training in vocations needed in the locality which shall be open to elementary school graduates: Provided, finally, That the school shall open, as soon as feasible, two-year post secondary technical courses."}},{"id":"PH-H5091-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school during the fiscal year nineteen hundred seventy one. Thereafter, such sum as may be needed for operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5091-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, September 30, 1972"}}],"pack":"ph-p72"};
  FT["PH-H5092"] = {"id":"PH-H5092","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6594_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of Dona Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Increasing the Bed Capacity of Dona Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["labor","health"],"docNumber":"Republic Act No. 6594","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6594_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5092-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of Dona Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, is hereby increased from fifty to one hundred beds."}},{"id":"PH-H5092-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such sums as are necessary to carry into effect the provisions of this Act are authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, during the current fiscal year and, thereafter, shall be deemed included in the annual General Appropriations Act."}},{"id":"PH-H5092-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5093"] = {"id":"PH-H5093","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6595_1972.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Further Amending Certain Sections of Republic Act Numbered Five Thousand Eighty-Eight, Entitled \"An Act Converting Eulogio Rodriguez Vocational High School Into the Eulogio Rodriguez Memorial School of Arts and Trades\" and Amending Certain Sections of Republic Act Numbered Four Thousand Seventy-Two, Entitled \"An Act Providing for the Establishment of a Vocational Technical Department of the Eulogio Rodriguez Vocational High School in the City of Manila.\"","orig":"An Act Further Amending Certain Sections of Republic Act Numbered Five Thousand Eighty-Eight, Entitled \"An Act Converting Eulogio Rodriguez Vocational High School Into the Eulogio Rodriguez Memorial School of Arts and Trades\" and Amending Certain Sections of Republic Act Numbered Four Thousand Seventy-Two, Entitled \"An Act Providing for the Establishment of a Vocational Technical Department of the Eulogio Rodriguez Vocational High School in the City of Manila.\""},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 6595","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6595_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1、2、3、4、5、7、8 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5093-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Eulogio Rodriguez Vocational High School in the City of Manila is hereby converted into an institute of science and technology to be known as the Eulogio \"AMANG\" Rodriguez Institute of Science and Technology."}},{"id":"PH-H5093-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one of Republic Act Numbered Four thousand seventy-two is further amended to read as follows:\n\""}},{"id":"PH-H5093-A1_2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The institute is hereby authorized to establish a trade technical education department, vocational-technical teacher education department, technology department, science and arts department, graduate education department and offer such other opportunity and technician courses essential to meet the needs of Manila and other metropolitan area.\""}},{"id":"PH-H5093-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section two of the same Act is further amending to read as follows:\n\""}},{"id":"PH-H5093-A2_2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Eulogio \"AMANG\" Rodriguez Institute of Science and Technology shall be headed by a president of the institute of science and technology whose salary shall not be less than twenty-five thousand pesos per annum. The present head of the school shall become its first president. Thereafter, the president shall be appointed by the Secretary of Education upon the recommendation of the Director of Vocational Education. The heads of the various departments together with the other personnel of this institute, shall be appointed by the Director of Vocational Education upon the recommendation of its president subject to existing- rules and regulations.\""}},{"id":"PH-H5093-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section three of the same Act is further amended to read as follows:\n\""}},{"id":"PH-H5093-A3_2","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The administrative officer, supervisors and heads of departments shall each receive not less than twelve thousand pesos per annum and each instructor or professor and other personnel shall receive the same amount of salary as those holding similar positions at the Pamantasan ng Lungsod ng Maynila. The head of the graduate education department shall also act as vice president, of the institute with an annual salary equal to the amount of salary received by the vice president of the Philippine College of Arts and Trades.\""}},{"id":"PH-H5093-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section four of the same Act is further amended to read as follows:\n\""}},{"id":"PH-H5093-A4_2","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The school registrar, guidance counselors or placement coordinator with an annual salary of ten thousand pesos shall be appointed by the Director of Vocational Education upon the recommendation of the president and shall be paid out of city funds.\""}},{"id":"PH-H5093-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section five of the same Act is further amended to read as follows:\n\""}},{"id":"PH-H5093-A5_2","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The operation and maintenance of the technical education department and technology department shall be financed by the National Government. The appointment of instructors and professors to these departments shall be based upon proven competence and not necessarily upon qualification in civil service examinations.\""}},{"id":"PH-H5093-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section six of the same Act is further amended to read as follows:\n\"Section 6, The operation and maintenance of the science and arts department, vocational-technical teacher education department, the graduate education department and secondary department of the school, including its day and evening vocational school departments, but excluding the technical education department and technology department shall be financed by the Government of the City of Manila. In addition to funds taken from other sources, at least, fifteen percent of the funds raised for the City of Manila under Republic Act Numbered Five thousand four hundred and forty-seven as amended must be appropriated for the said departments of the institute. The present teachers and other personnel of Rodriguez Vocational High School shall continue in the same capacity under the secondary and vocational departments of the institute of science and technology. The secondary department shall have a principal whose salary shall not be less than ten thousand pesos per annum and assistant principals who shall be appointed by the Director of Vocational Education upon the recommendation of the president of the institute.\""}},{"id":"PH-H5093-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The same Act is further amended by inserting immediately after Section six thereof a new section which shall read as follows:\n\"Section 6-A. The City Government of Manila is authorized to establish a vocational-technical school in each of its congressional districts as branches of the Eulogio \"AMANG\" Rodriguez Institute of Science and Technology or may convert any of its existing secondary schools upon recommendation of the President of the Eulogio \"AMANG\" Rodriguez Institute of Science and Technology in consultation with the City Government of Manila and approval by the Secretary of Education. Each of these district branches shall be headed by a vocational technical superintendent with salary as much as those given to school of arts and trades superintendents. The operation and maintenance of these district vocational-technical schools shall be financed by the City Government of Manila.\""}},{"id":"PH-H5093-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section seven of the same Act is further amended to read as follows:\n\""}},{"id":"PH-H5093-A7_2","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Provincial students may be enrolled in the said institute after all qualified resident applicants in the City of Manila shall have been admitted.\""}},{"id":"PH-H5093-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"There is hereby inserted between Sections seven and eight of the same Act two new sections to be known as Section seven-A and Section seven-B to read as follows:\n\"Section 7-A. The Secretary of Education is hereby empowered to locate and acquire or cause to be located and acquired an additional school site for the establishment of the technical education department and other departments of the Eulogio \"AMANG\" Rodriguez Institute of Science and Technology which may be public or private land situated within the City of Manila. The city government shall provide funds for this purpose.\n\"Section 7-B. The Director of Vocational Education with the approval of the Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purposes of this Act.\""}},{"id":"PH-H5093-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section eight of the same Act is further amended to read as follows:\n\""}},{"id":"PH-H5093-A8_2","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The sum of one million five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the technical education department and technology department of the Eulogio \"AMANG\" Rodriguez Institute of Science and Technology during the fiscal year nineteen hundred seventy-three. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act.\""}},{"id":"PH-H5093-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5094"] = {"id":"PH-H5094","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6596_1972.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Certain Sections of Republic Act Numbered Forty-One Hundred Eighty-Nine Converting the Iloilo Normal School to West Visayas State College.","orig":"An Act Amending Certain Sections of Republic Act Numbered Forty-One Hundred Eighty-Nine Converting the Iloilo Normal School to West Visayas State College."},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 6596","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-09-30","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6596_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1、2 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5094-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Forty-one hundred eighty-nine is hereby amended to read as follows:\n\""}},{"id":"PH-H5094-A1_2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The present Iloilo Normal School located in Iloilo City, Philippines, is hereby converted into the West Visayas State College, offering general education and teacher education courses leading to the degrees of Bachelor of Arts (A.B.), Bachelor of Science in Education (B.S.E.), Master of Arts (M.A.) in Education and other courses of university level.\""}},{"id":"PH-H5094-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two of the same Act is hereby amended to read as follows:\n\""}},{"id":"PH-H5094-A2_2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The main purposes of said college are to give general cultural education and to provide professional and technical instruction in the field of education and in other fields.\""}},{"id":"PH-H5094-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Subsection b of Section five of the same Act is hereby amended to read as follows:\n\"b. To confer the degrees of Bachelor of Arts, Bachelor of Science in Education, Master of Arts in Education, and other degrees to successful candidates for graduation.\""}},{"id":"PH-H5094-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5095"] = {"id":"PH-H5095","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6597_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Allen市","en":"An Act Establishing a Pilot Project for Animal Industry in the Municipality of Allen, Province of Northern Samar, to Be Known as Allen Animal Industry Pilot Project, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing a Pilot Project for Animal Industry in the Municipality of Allen, Province of Northern Samar, to Be Known as Allen Animal Industry Pilot Project, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6597","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6597_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5095-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, under the direct supervision of the Director of Animal Industry, a pilot project for animal industry in the Municipality of Allen, Province of Northern Samar, to be known as Allen Animal Industry Pilot Project."}},{"id":"PH-H5095-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said pilot Project during the fiscal year nineteen hundred seventy. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5095-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5096"] = {"id":"PH-H5096","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6598_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Butuan市","en":"An Act Establishing An Animal Breeding Station in the City of Butuan, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Animal Breeding Station in the City of Butuan, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6598","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6598_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5096-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Animal Industry, an animal breeding station in the City of Butuan, to be known as the Butuan City Animal Breeding Station."}},{"id":"PH-H5096-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment of the said animal breeding station and for the purchase of breeding animals, supplies and materials and such other expenses as may be necessary to carry out the Purpose of this Act. Thereafter, such sum as may be needed for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H5096-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5097"] = {"id":"PH-H5097","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6599_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Section Two of Republic Act Numbered Twenty-Six Hundred Fifty-Nine By Increasing the Bed Capacity of Palompon General Hospital, and Authorizing the Appropriation of Additional Funds Therefor.","orig":"An Act Amending Section Two of Republic Act Numbered Twenty-Six Hundred Fifty-Nine By Increasing the Bed Capacity of Palompon General Hospital, and Authorizing the Appropriation of Additional Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6599","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6599_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 2 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5097-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered twenty-six hundred fifty-nine is hereby amended to read as follows:\n\""}},{"id":"PH-H5097-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of one hundred fifty thousand pesos for the construction of the Palompon General Hospital and for its operation and maintenance: Provided: That this hospital shall have at least seventy-five beds.\""}},{"id":"PH-H5097-A2_2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5098"] = {"id":"PH-H5098","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6600_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Roxas市","en":"An Act Establishing An Artificial Breeding Center in the Municipality of Roxas, Province of Oriental Mindoro, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Artificial Breeding Center in the Municipality of Roxas, Province of Oriental Mindoro, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6600","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6600_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5098-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, under the supervision of the Bureau of Animal Industry, an artificial breeding center in the Municipality of Roxas, Province of Oriental Mindoro, at a site to be selected by the Director of Animal Industry through donation, to be known as the Roxas Artificial Breeding Center."}},{"id":"PH-H5098-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the construction of office-laboratory building, animal sheds, equipment, supplies and materials and such other expenses as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H5098-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5099"] = {"id":"PH-H5099","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6601_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立San Pedro市","en":"An Act Establishing An Artificial Breeding Center in the Municipality of San Pedro, Province of Oriental Mindoro, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Artificial Breeding Center in the Municipality of San Pedro, Province of Oriental Mindoro, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6601","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6601_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5099-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, under the supervision of the Bureau of Animal Industry, an artificial breeding center in the Municipality of San Pedro, Province of Oriental Mindoro, at a site to be selected by the Director of Animal Industry through donation, to be known as the San Pedro Artificial Breeding Center."}},{"id":"PH-H5099-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the construction of office-laboratory building, animal sheds, equipment, supplies and materials and such other expenses as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H5099-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5100"] = {"id":"PH-H5100","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6602_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing a Soil and Water Conservation Research and Demonstration Center in the Municipality of Naujan Province of Oriental Mindoro, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing a Soil and Water Conservation Research and Demonstration Center in the Municipality of Naujan Province of Oriental Mindoro, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6602","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6602_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5100-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a soil and water conservation research and demonstration center in the Municipality of Naujan, Province of Oriental Mindoro. The said center shall be under the supervision of the Director of Soils and shall be subject to the provisions of Republic Act Numbered Six hundred sixty-two, as amended."}},{"id":"PH-H5100-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of three hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the research and demonstration center for the fiscal year nineteen hundred and seventy-two. Thereafter, such sums as be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5100-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5101"] = {"id":"PH-H5101","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6603_1972.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Bicol Telephone and Telegraph, Inc. a Franchise to Establish, Operate and Maintain Telephone System and Radio Telephone Stations in the Provinces of Albay and Sorsogon.","orig":"An Act Granting Bicol Telephone and Telegraph, Inc. a Franchise to Establish, Operate and Maintain Telephone System and Radio Telephone Stations in the Provinces of Albay and Sorsogon."},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 6603","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6603_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5101-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, and the provisions of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes\"; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their respective amendments, and other applicable laws, there is hereby granted to Bicol Telephone and Telegraph Incorporated, hereinafter referred to as the \"grantee\" a franchise to establish, install, operate and maintain in the provinces of Albay and Sorsogon, public telephone system for domestic services with the authority to receive and transmit messages, impressions, by means of electricity, electromagnet waves or any other kind of energy force, variations or impulses howsoever conveyed, transmitted or radiated through other medium and to communicate from within the grantee's station or stations which right and privileges shall continue to be in force during the time that the Government has not established similar services at the places selected by the grantee, but shall not exceed twenty-five years from the date of the approval of this Act and for such purposes and to charge and to receive compensation therefor by tolls, and charges."}},{"id":"PH-H5101-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subject to the limitations and procedure prescribed by law, the grantee is authorized to exercise the right of eminent domain, insofar as may be reasonably necessary to further the establishment and efficient maintenance and operation of its telephone systems. The grantee is authorized to construct, maintain, and erect poles, structures, string wires, build conduits, to make excavation, lay cables, and to construct, maintain and use such other approved and generally accepted means of electrical conduction in, on, over, or under the public roads, government rights of way, lands, bridges, rivers, waters, streets, lanes, alleys, avenues, sidewalks in the provinces, where the grantee's telephone system is located: Provided, That poles erected by the grantee shall be of such a height of at least ten feet above the level of the ground, providing a height of at least fifteen feet in crossing roads or streets, and shall be so placed as not to be a danger to public safety, and any public place, highway, street, lane, alley, avenue, sidewalk or bridge disturbed, altered or changed by reason of the erection of poles, or other supports, or the laying underground of wires or other conductors, or of conduits, shall be repaired and replaced in a workmanlike manner by said grantee, its successors or assigns, to the satisfaction of the Secretary of Public Works and Communications. Should the grantee, its successors or assigns, after ten days notice from said authority, fail, refuse or neglect to replace any Part of a public place, road, highway, street, lane, alley, avenue, sidewalk or bridge altered, changed or disturbed by said grantee, its successors or assigns, then the Secretary of public Works and Communications shall have the right to have the same repaired and placed in good order and condition at the cost and expense of the grantee, its successors or assigns."}},{"id":"PH-H5101-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee may install, maintain and operate radio-telephone equipment to furnish an economic medium of communications in and between the provinces of Albay and Sorsogon and between the grantee's telephone system to other local telephone systems. The radiotelephone equipment shall not be used to transmit telegraphic messages for hire."}},{"id":"PH-H5101-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall supply telephone service in said provinces, where it may have established a local telephone exchange, to any applicant within thirty days after the date of his application, up to the limit of the capacity of the telephone system of said grantee: Provided, That in case the point at which the telephone service is to be supplied is more than five hundred meters from the local exchange lines operated by said grantee, the latter shall not be obliged to furnish said service, unless the applicant for telephone service defrays the actual expenses for the poles and wires and Installation thereof necessary for such service and in such case the Public Service Commission may extend the time which the grantee must furnish such services beyond the said period of thirty days."}},{"id":"PH-H5101-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the first of said stations shall be placed in operation and granted upon the express condition that the same shall be begun within one year from the date of the approval of this Act and be completed within two years from said date."}},{"id":"PH-H5101-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This franchise shall not take effect nor shall any powers thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used, so selected to avoid interference to existing radio stations and to permit the expansion of the grantee's services."}},{"id":"PH-H5101-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order to cause the closing of the said stations or to authorize the temporary use and operation thereof by any department of the Government upon payment of just compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5101-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5101-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep a separate account of the gross receipts of the business transacted by it in the Philippines and shall furnish to the Auditor General and the Treasurer of the Philippines a copy of such account not later than the thirty-first day of January of each year for the preceding year. All the books and accounts of the grantee pertaining to its business shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts of the Philippines, under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H5101-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H5101-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee, shall file a bond in the amount of twenty thousand pesos to guarantee for the full compliance and fulfillment of the conditions under which this franchise is granted. If, after four years from date of the approval of this Act, the grantee shall have fulfilled said conditions or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H5101-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise, to any person, firm, company, or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to all the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation of other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H5101-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Within sixty days after the approval of this Act, the grantee shall file with the Secretary of Public of Works and Communications its written acceptance of this franchise and of all the terms and conditions hereof, and in default of such acceptance, within the time so limited, this franchise shall become null and void."}},{"id":"PH-H5101-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The rates of the telephone service, flat rates, toll rates as well as measured rates and radio rates shall be subject to the approval of the Public Service Commission."}},{"id":"PH-H5101-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The grantee, its successors or assigns, may install, maintain, operate, or lease such telephone system, lines, cables, necessary to efficiently carry out the purpose of this franchise and shall not begin any construction of the telephone system without first obtaining a certificate of public convenience and necessity from the Public Service Commission."}},{"id":"PH-H5101-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The Philippine Government, including any and all of its departments and bureaus in the location where the grantee's telephone exchanges are located, shall have the privilege, without compensation, of using such space on the poles of the grantee for wire attachments, cable attachments, or cross-arms attachments as will not impair the public safety, employee's safety or service requirements of the grantee."}},{"id":"PH-H5101-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"In consideration of the franchise and rights hereby granted, and any provision of law to the contrary notwithstanding, the grantee shall pay the same taxes as are now or may hereafter be required by law from other individuals, co-partnerships, private or quasi-public associations, corporations, or joint stock companies, on real estate buildings and other personal property.\nIn consideration of the franchise and rights hereby granted, the grantee shall pay a franchise tax equal to five per centum of the gross earnings under this franchise three per centum of which shall accrue to the National Government and two per centum to the municipality where the franchise is being operated."}},{"id":"PH-H5101-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H5101-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"This franchise shall not be interpreted to mean an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5101-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5102"] = {"id":"PH-H5102","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6604_1972.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Further Amending Republic Act Numbered Forty Hundred and Twelve, Entitled \"An Act Granting Pototan Electric Light and Power Corporation, a Franchise for Electric Light, Heat and Power System in the Municipality of Pototan, Province of Iloilo.\"","orig":"An Act Further Amending Republic Act Numbered Forty Hundred and Twelve, Entitled \"An Act Granting Pototan Electric Light and Power Corporation, a Franchise for Electric Light, Heat and Power System in the Municipality of Pototan, Province of Iloilo.\""},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 6604","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6604_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 1 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5102-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Forty hundred and twelve, as amended, is hereby further amended, to read as follows:\n\""}},{"id":"PH-H5102-A1_2","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One Hundred thirty-two, and to the provisions of the Constitution, there is granted to Pototan Electric Light and Power Corporation in the Municipality of Pototan, Province of Iloilo, for a period of twenty-five years from approval of this Act, right, privilege and authority to construct, maintain and operate light, heat and/or power system and an ice plant for the purpose of generating, distributing, electric light, heat and/or power and manufacturing ice for distribution and sale within the said municipality, all the municipalities of the fourth legislative district of Iloilo, and in the neighboring municipalities.\""}},{"id":"PH-H5102-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two-C of the same Act is amended to read as follows:\n\"Section 2-C. If the grantee shall not commence the manufacture and distribution of ice in the Municipality of Pototan, all the municipalities of the fourth legislative district of Iloilo and the neighboring municipalities, within two years from the approval of this amendatory Act, unless prevented by an act of God, force majeure, martial law, riot, civil commotion, usurpation by military power and any other cause beyond the grantee's control, then the franchise authorizing the manufacture and sale of ice shall be null and void.\""}},{"id":"PH-H5102-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section two-D, of the same Act is amended to read as follows:\n\"Section 2-D. This franchise is granted subject to the provisions of the Constitution and Commonwealth Act Numbered One hundred forty-six, as amended, and with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines, when public interest so requires.\""}},{"id":"PH-H5102-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise shall be inoperative in those municipalities where there is an existing franchise holder for the service herein granted."}},{"id":"PH-H5102-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5103"] = {"id":"PH-H5103","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6605_1972.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Nueva Era市","en":"An Act Converting the Nueva Era Breeding Station in the Municipality of Nueva Era, Province of Ilocos Norte to a Stock Farm and Breeding Station, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Converting the Nueva Era Breeding Station in the Municipality of Nueva Era, Province of Ilocos Norte to a Stock Farm and Breeding Station, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 6605","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6605_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5103-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Nueva Era Breeding Station in the Municipality of Nueva Era, Province of Ilocos Norte is hereby converted to a stock farm and breeding station, to be known as Nueva Era Stock Farm and Breeding Station."}},{"id":"PH-H5103-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of the Bureau of Animal Industry shall issue such rules and regulations which may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5103-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the conversion of said breeding station to a stock farm and breeding station."}},{"id":"PH-H5103-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5104"] = {"id":"PH-H5104","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6606_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Soccoro市","en":"An Act Establishing An Artificial Breeding Center in the Municipality of Soccoro, Province of Oriental Mindoro, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Artificial Breeding Center in the Municipality of Soccoro, Province of Oriental Mindoro, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6606","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6606_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5104-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established, under the supervision of the Bureau of Animal Industry, an artificial breeding center in the Municipality of Soccoro, Province of Oriental Mindoro, at a site to be selected by the Director of Animal Industry through donation, to be known as the Soccoro Artificial Breeding Center."}},{"id":"PH-H5104-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of funds in the National Treasury not otherwise appropriated, for the construction of the office-laboratory building, animal sheds, equipment, supplies and materials and such other expenses as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H5104-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5105"] = {"id":"PH-H5105","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6607_1972.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Three Hundred Thousand Pesos for the Development, Maintenance and Improvement of the Damortis National Seashore Park Situated in the Province of La Union.","orig":"An Act Appropriating Three Hundred Thousand Pesos for the Development, Maintenance and Improvement of the Damortis National Seashore Park Situated in the Province of La Union."},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 6607","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6607_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5105-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of three hundred thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated, which shall be expended by the Director of Parks and Wildlife, for the development, maintenance and improvement of the Damortis National Seashore Park situated in the Province of La Union, for the fiscal year nineteen hundred and seventy-three. Thereafter, such sums as may be necessary for the further development, maintenance and improvement of the park shall be included in the annual General Appropriations Act."}},{"id":"PH-H5105-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5106"] = {"id":"PH-H5106","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6608_1972.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Certain Provisions of Republic Act Numbered Fifty-Nine Hundred and Six, Known as the Charter of the City of Puerto Princesa, and for Other Purposes.","orig":"An Act Amending Certain Provisions of Republic Act Numbered Fifty-Nine Hundred and Six, Known as the Charter of the City of Puerto Princesa, and for Other Purposes."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6608","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6608_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 8 条，缺 4、5、6、7）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5106-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seven of Republic Act Numbered Fifty-nine hundred and six is hereby amended to read as follows;\n\"Section 7. The City Mayor .—The City Mayor shall be the chief executive of the city. He shall be elected by the qualified voters of the city and shall hold office for a term of four years. He shall receive a compensation of not less than twelve thousand six hundred pesos per annum and shall be entitled in addition to his salary, to a commutable allowance of not exceeding six thousand pesos per annum . No person shall be eligible for election as City Mayor, unless he is not less than thirty years of age, a resident of the city for the last two years prior to his election and a qualified voter therein.\""}},{"id":"PH-H5106-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section eight of the same Act is hereby amended to read as follows:\n\""}},{"id":"PH-H5106-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The City Vice-Mayor. —There shall be a City Vice Mayor who shall be chosen in the same manner as the City Mayor, and shall possess the same qualifications as that of the City Mayor. He shall perform the duties, and exercise the powers of the City Mayor in the event of the death, sickness, absence or other temporary incapacity of the incumbent or in the event of permanent vacancy in the position of the City Mayor. If, for any reason the City Vice Mayor is temporarily incapacitated in the performance of the duties of the City Mayor, or said office of the City Vice Mayor is vacant, the duties and powers of the City Mayor shall be performed and exercised by the councilor who obtained the highest number of votes during the election for members of the City Council. The City Vice-Mayor shall be the presiding officer of the City Council, with no right to vote except in case of tie and shall perform such other duties as may be assigned to him by the City Mayor or prescribed by law or ordinance. He shall receive a compensation of not less than seven thousand eight hundred pesos per annum .\n\"The Vice Mayor whenever he is designated as Acting Mayor or any other elective official designed by the Mayor as Acting Mayor shall receive compensation equivalent to the salary of the Mayor during the inclusive period thereof.\""}},{"id":"PH-H5106-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first paragraph of Section ten of the same Act is hereby amended to read as follows:\n\""}}],"pack":"ph-p72"};
  FT["PH-H5107"] = {"id":"PH-H5107","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6609_1972.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Amending Certain Items in Republic Act Numbered Fifty-Nine Hundred Seventy-Nine (Re Public Works Projects for the Province of Capiz).","orig":"An Act Amending Certain Items in Republic Act Numbered Fifty-Nine Hundred Seventy-Nine (Re Public Works Projects for the Province of Capiz)."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6609","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6609_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5107-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sums appropriated in items (a), (b), (c), (l), (m), (n), and (o), pages 1936-1937, subparagraph 18, for the Province of Capiz, paragraph \"a\", Title M, Section four of Republic Act Numbered Fifty-nine hundred seventy-nine, to wit:\n\"(a) Dumalag Electrification System (including purchase of equipment and supplies) P1,000,000 \"(b) Jamindan Electrification System (including purchase of equipment and supplies) 1,000,000 \"(c) T a p a z Electrification System (including purchase of equipment and supplies) 1,000,000 \"(l) Mambusao Electrification System (including purchase of equipment and supplies) 3,000,000 \"(m) Sapian Electrification System (including- purchase of equipment and supplies) 2,000,000 \"(n) Sigma Electrification System (including purchase of equipment and supplies) 3,000,000 \"(o) Jagnaya Electrification System (including purchase of equipment and supplies), Jamindan 600,000\" are hereby reappropriated in accordance with the following sections."}},{"id":"PH-H5107-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subparagraph 18, for the Province of Capiz, page 9, paragraph \"a\", Title A, Section one of Republic Act Numbered Fifty-nine hundred seventy-nine, is amended by adding thereto a new item which shall read as follows:\n(1) Provincial Capitol of Capiz including acquisition of site 4,000,000\""}},{"id":"PH-H5107-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Subparagraph 18, for the Province of Capiz, page 219, paragraph \"c\", Title B, Section one of the same Act is amended by adding thereto a new item which shall read as follows:\n\"(ez) Tapaz Bridge 450,000\""}},{"id":"PH-H5107-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Subparagraph 18, Group II, page 1063, paragraph \"a\" Section two of the same Act is amended by adding thereto the following new items which shall read as follows:\n\"(db) Dumalag various public works projects 350,000 \"(dc) Jamindan various public works projects 350,000 \"(dd) Mambusao various public works projects 400,000 \"(de) Sapian various public works projects 350,000 “(df) Sigma various public works projects 350,000 \"(dg) Tapaz various public works projects 150,000 “(dh) Villareal Hall of Justice, Mambusao 200,000"}},{"id":"PH-H5107-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Page 1984, paragraph \"b\", Title J, Section five of the same Act is amended by adding thereto a new item which shall read as follows:\n“815.\nPort of Sapian, Capiz 3,000,000\""}},{"id":"PH-H5107-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, October 23, 1972."}}],"pack":"ph-p72"};
  FT["PH-H5108"] = {"id":"PH-H5108","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6610_1972.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring the Central Catanduanes (Boctot) Park in the Province of Catanduanes as the Alberto National Memorial Park.","orig":"An Act Declaring the Central Catanduanes (Boctot) Park in the Province of Catanduanes as the Alberto National Memorial Park."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6610","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6610_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5108-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Central Catanduanes (Boctot) Park in the Province of Catanduanes is hereby declared as Alberto National Memorial Park."}},{"id":"PH-H5108-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5109"] = {"id":"PH-H5109","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6611_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Dinagat市","en":"An Act Establishing An Emergency Hospital in the Municipality of Dinagat, Province of Surigao Del Norte, to Be Known as Dinagat Emergency Hospital, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Dinagat, Province of Surigao Del Norte, to Be Known as Dinagat Emergency Hospital, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6611","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6611_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5109-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Director of Medical Services, an emergency hospital in the Municipality of Dinagat, Province of Surigao del Norte, to be known as Dinagat Emergency Hospital."}},{"id":"PH-H5109-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred seventy-two. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5109-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5110"] = {"id":"PH-H5110","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6612_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of Dinagat Emergency Hospital in the Municipality of Dinagat, Province of Surigao Del Norte, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Increasing the Bed Capacity of Dinagat Emergency Hospital in the Municipality of Dinagat, Province of Surigao Del Norte, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6612","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6612_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5110-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of Dinagat Emergency Hospital in the Municipality of Dinagat, Province of Surigao del Norte, is hereby increased from twenty-five to fifty beds."}},{"id":"PH-H5110-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said hospital during the fiscal year nineteen hundred and seventy-two. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5110-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5111"] = {"id":"PH-H5111","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6613_1972.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring a Policy of the State to Adopt Modern Scientific Methods to Moderate Typhoons and Prevent Destruction By Floods Rains and Droughts, Creating a Council on Typhoon Moderation and Flood Control Research and Development, Providing for Its Powers and Functions and Appropriating Funds Therefor.","orig":"An Act Declaring a Policy of the State to Adopt Modern Scientific Methods to Moderate Typhoons and Prevent Destruction By Floods Rains and Droughts, Creating a Council on Typhoon Moderation and Flood Control Research and Development, Providing for Its Powers and Functions and Appropriating Funds Therefor."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 6613","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6613_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5111-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared to be the policy of the State to adopt a typhoon moderation and flood control research and development program for moderating typhoons by reducing their intensity and minimizing the destructive effects of floods, rains and droughts through scientific means, for the purpose of preventing widespread devastation to property and protecting the People and security of the nation."}},{"id":"PH-H5111-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In order to carry out the foregoing policy, the government shall:\na. Undertake research on the structure, development and motion of typhoons;\nb. Improve means of predicting typhoons and consequential floods;\nc. Gather and organize climatological and hydrological data for flood prevention and control and for agro-industrial development;\nd. Utilize scientific measures to minimize the intensity of typhoons and destruction by floods, rains and droughts: and\ne. Study the environmental impact of such measures and adopt necessary precautions to prevent loss or destruction,"}},{"id":"PH-H5111-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"To implement the provisions of this Act, there is hereby created a Council on Typhoon Moderation and Flood Control Research and Development under the Office of the President, hereinafter referred to as the \"Council\". The Council shall be composed of the Executive Secretary as Chairman ex-officio , the Secretary of National Defense as Vice-Chairman ex-officio , the Chairman of the National Science Development Board, the Secretary of Public Works and Communications, the Secretary of Agriculture and Natural Resources, the Undersecretary of Foreign Affairs, and the Director of the Weather Bureau, as members ex-officio .\nThe Council shall develop and formulate a typhoon moderation and flood control research and development program within one year after the approval of this Act and shall monitor its implementation. It shall coordinate planning and programming of all government activities and resources in relation thereto. It shall advise the President on measures to prevent or mitigate damage arising from typhoons, floods, rains and droughts. It shall represent the government on all matters pertinent to the research and development provided for in this Act in national, regional and international conferences.\nThe Council shall submit annually a report of its activities, together with a statement of the funds released to it and the expenditures made therefrom, to the presiding officers of both Houses of Congress and to the respective chairmen of the committees on science, agriculture, natural resources, public works, communications, national defense and security of both Houses. The report shall include a description of all projects monitored by the Council indicating their status. The Council shall recommend to Congress such legislation as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H5111-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Weather Bureau, hereinafter referred to as the \"Bureau\", shall be the implementing arm of the Council. The Director of said Bureau shall be the Executive Director of the Council.\nThe Bureau shall establish, install, operate and maintain climatological and hydrological stations, synoptic stations, radar stations, upper air stations (radiosonde and radiowind), automatic picture transmission ground stations, a weather communications network and warning system, and a research center using computers, aircraft and other modern devices. Insofar as possible, such stations shall be grouped together so as to assure maximum economy and efficiency. The Philippine Air Force shall assist the Bureau in air operations.\nIn the installation of radar stations, the regions of Western Visayas, Northern Mindanao and Southern Mindanao which are not covered by the present weather radar network shall be given priority."}},{"id":"PH-H5111-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sum of ten million pesos (P10,000,000.00) is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, and an additional appropriation of ten million pesos (P10,000,000,00) annually .shall be included in the General Appropriations Act for each of the next four years, to carry into effect the provisions of this Act: Provided, That the sum of Four Million One Hundred Thousand Pesos, or so much of the appropriations as may be necessary, shall be set aside annually to be used exclusively for the purchase and operation of the type of aircraft required to carry out the purposes of this Act."}},{"id":"PH-H5111-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5112"] = {"id":"PH-H5112","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6614_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Provide for the Period and Increase of Assessments of Real Property for Taxation Purposes.","orig":"An Act to Provide for the Period and Increase of Assessments of Real Property for Taxation Purposes."},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 6614","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6614_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5112-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law or city charter to the contrary notwithstanding, no revised assessment of real estate for taxation purposes shall be made within five years from the last preceding assessment, and no increase or decrease of assessment at any one time shall be more than twenty-five per centum in the case of commercial and industrial lots; fifteen per centum in case of agricultural and residential lots not actually occupied by the owner and ten per centum in case of residential lots actually occupied by the owner, of the last preceding assessed value: Provided, That the limitations herein shall not apply if by reason of public improvements the-nature of the real estate has been changed from rural to urban or from residential to commercial and industrial site: Provided, further , That the corresponding provincial or city assessor shall undertake the revision of assessments every five years."}},{"id":"PH-H5112-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws, Acts, parts of Acts, city charters, ordinances and resolutions which are inconsistent with this Act are hereby repealed."}},{"id":"PH-H5112-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5113"] = {"id":"PH-H5113","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6615_1972.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Requiring Government and Private Hospitals and Clinics to Extend Medical Assistance in Emergency Cases.","orig":"An Act Requiring Government and Private Hospitals and Clinics to Extend Medical Assistance in Emergency Cases."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6615","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6615_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5113-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"All government and private hospitals or clinics duly licensed to operate as such are hereby required to render immediate emergency medical assistance and to provide facilities and medicine within its capabilities to patients in emergency cases who are in danger of dying and/or who may have suffered serious physical injuries."}},{"id":"PH-H5113-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The expenses and losses of earnings incurred by a private hospital or clinic for medicines, facilities and services beyond first aid extended to emergency cases as required herein, and not to exceed fifty thousand pesos per year, shall be deductible expenses and losses for income tax purposes which may be carried over for a period of five years, any provision of law or regulation to the contrary notwithstanding."}},{"id":"PH-H5113-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Any hospital director, administrator, officer-in-charge or physician in the hospital, medical center or Clinic, who shall refuse or fail without good cause to render the appropriate assistance pursuant to the requirements of section one after said case had been brought to his attention, or any nurse, midwife or medical attendant who shall refuse to extend the appropriate assistance, subject to existing rules, or neglect to notify or call a physician shall be punished by imprisonment of one month and one day to one year and one day, and a fine of three hundred pesos to one thousand pesos, without prejudice to the provisions of Republic Act Numbered Twenty-three hundred eighty-two in the case of physicians.\nIn the case of Government hospitals, the imposition of the penalty upon the person or persons guilty of the violations shall be without prejudice to the administrative action that might be proper.\nIn the case of private hospitals, aside from the imposition of penalty upon the person or persons guilty of the violations, the license of the hospital to operate shall, whenever justified, be suspended or revoked.\""}},{"id":"PH-H5113-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Subject to the approval of the Secretary of Health, the Bureau of Medical Services shall promulgate the necessary rules and regulations to carry out the provisions of this Act."}},{"id":"PH-H5113-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Any law or laws or parts thereof inconsistent with the provisions of this Act is hereby repealed."}},{"id":"PH-H5113-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5114"] = {"id":"PH-H5114","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6616_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of An Emergency Hospital in Barrio Calantac, Municipality of Alcala, Province of Cagayan, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Providing for the Establishment of An Emergency Hospital in Barrio Calantac, Municipality of Alcala, Province of Cagayan, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6616","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6616_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5114-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the Bureau of Medical Services, a twenty-five-bed emergency hospital in Barrio Calantac, Municipality of Alcala, Province of Cagayan, to be known as the Central Cagayan Emergency Hospital."}},{"id":"PH-H5114-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment and construction of said hospital as well as the purchase of equipment and facilities thereof. The annual maintenance of said hospital shall be in accordance with the provisions of Republic Act Numbered Nineteen hundred thirty-nine."}},{"id":"PH-H5114-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5115"] = {"id":"PH-H5115","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6617_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Biri市","en":"An Act Establishing An Emergency Hospital in the Municipality of Biri, Province of Northern Samar, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Biri, Province of Northern Samar, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6617","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6617_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5115-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Medical Services, an emergency hospital in the Municipality of Biri, Province of Northern Samar."}},{"id":"PH-H5115-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred seventy-two. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5115-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5116"] = {"id":"PH-H5116","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6618_1972.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Binidayan市","en":"An Act Establishing An Emergency Hospital in the Municipality of Binidayan, Province of Lanao Del Sur, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Binidayan, Province of Lanao Del Sur, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6618","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6618_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5116-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a twenty-bed capacity emergency hospital within the Municipality of Binidayan, Province of Lanao del Sur, the appropriate site to be determined by the Municipal Council of said municipality in consultation with the Director of Medical Services."}},{"id":"PH-H5116-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall, upon approval of this Act, promulgate the necessary rules and regulations to carry into effect the provisions of this Act."}},{"id":"PH-H5116-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry into effect the provisions of this Act for fiscal year nineteen hundred and seventy-three. Thereafter, the sums necessary for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H5116-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5117"] = {"id":"PH-H5117","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6619_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Badian市","en":"An Act Establishing An Emergency Hospital in the Municipality of Badian, Province of Cebu, to Be Known as the Badian Emergency Hospital, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Badian, Province of Cebu, to Be Known as the Badian Emergency Hospital, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6619","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6619_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5117-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Director of Medical Services, an emergency hospital in the Municipality of Badian, Province of Cebu, to be known as the Badian Emergency Hospital."}},{"id":"PH-H5117-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred seventy-three. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5117-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
