  FT["PH-H5121"] = {"id":"PH-H5121","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6623_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Maripipi市","en":"An Act Establishing An Emergency Hospital in the Municipality of Maripipi, Sub-Province of Biliran, Province of Leyte, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Maripipi, Sub-Province of Biliran, Province of Leyte, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6623","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6623_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5121-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct Supervision of the Director of Medical Services, a twenty-five-bed emergency hospital in the Municipality of Maripipi, Subprovince of Biliran, Province of Leyte. The site for the said hospital shall be determined by the Municipal Council of Maripipi in consultation with the Director of Medical Services."}},{"id":"PH-H5121-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital for the fiscal year nineteen hundred seventy-three. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H5121-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5122"] = {"id":"PH-H5122","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6624_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of the Western Leyte General Hospital in the Municipality of Baybay, Province of Leyte, From Fifty to Seventy-Five Beds, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Increasing the Bed Capacity of the Western Leyte General Hospital in the Municipality of Baybay, Province of Leyte, From Fifty to Seventy-Five Beds, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6624","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6624_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5122-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Western Leyte General Hospital in the Municipality of Baybay, Province of Leyte, is hereby increased from fifty to seventy-five."}},{"id":"PH-H5122-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos, or so much thereof as may be necessary, is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act during the fiscal year nineteen hundred seventy-two. Thereafter, such sum as may be needed for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H5122-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5123"] = {"id":"PH-H5123","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6625_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity Op the Ormoc General Hospital in the City of Ormoc From Fifty to Seventy-Five, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Increasing the Bed Capacity Op the Ormoc General Hospital in the City of Ormoc From Fifty to Seventy-Five, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6625","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6625_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5123-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Ormoc General Hospital in the City of Ormoc is hereby increased from fifty to seventy-five beds."}},{"id":"PH-H5123-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act during the fiscal year nineteen hundred seventy-two. Such sum as may be needed for its operation and maintenance in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H5123-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5124"] = {"id":"PH-H5124","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6626_1972.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Siaton市","en":"An Act Establishing An Emergency Hospital in the Municipality of Siaton, Province of Negros Oriental, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing An Emergency Hospital in the Municipality of Siaton, Province of Negros Oriental, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6626","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6626_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5124-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national emergency hospital with a twenty-five-bed capacity in the Municipality of Siaton, Province of Negros Oriental."}},{"id":"PH-H5124-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5124-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred and seventy-three. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5124-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
  FT["PH-H5125"] = {"id":"PH-H5125","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1972/ra_6627_1972.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing Pilot Fish and Shrimp Farms and Nurseries in the Municipalities of Cantilan, Lianga, and Hinatuan, Province of Surigao Del Sur, and Authorizing the Appropriation of Funds Therefor.","orig":"An Act Establishing Pilot Fish and Shrimp Farms and Nurseries in the Municipalities of Cantilan, Lianga, and Hinatuan, Province of Surigao Del Sur, and Authorizing the Appropriation of Funds Therefor."},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 6627","issuingBody":"Congress of the Philippines","promulgatedDate":"1972-10-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1972/ra_6627_1972.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5125-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established and maintained under the supervision of the Fisheries Commissioner, pilot fish and shrimp farms and nurseries in the Municipalities of Cantilan, Lianga and Hinatuan, Province of Surigao del Sur."}},{"id":"PH-H5125-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry into effect the purpose of this Act during the fiscal year nineteen hundred and seventy-two. Thereafter, the amount of forty thousand pesos to defray expenses for the operation and maintenance of the project shall be included in the annual General Appropriations Act."}},{"id":"PH-H5125-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p72"};
